// Validate and normalize chat input
const body = $input.first().json.body || $input.first().json;

const query = body.query || body.message || body.question || '';
if (!query || query.trim() === '') {
  throw new Error('Query tidak boleh kosong');
}

const sessionId = body.session_id || body.sessionId || `sess_${Date.now()}_${Math.random().toString(36).substr(2,6)}`;
const chatHistory = body.chat_history || body.history || [];
const userId = body.user_id || 'anonymous';

return [{
  json: {
    query: query.trim(),
    session_id: sessionId,
    chat_history: chatHistory.slice(-10), // Keep last 10 messages
    user_id: userId,
    timestamp: new Date().toISOString()
  }
}];

// Build enriched response from AgriSensa API
const apiResponse = $input.first().json;
const inputData = $('✅ Input Validator').item.json;

const answer = apiResponse.answer || apiResponse.response || 'Maaf, tidak dapat memproses permintaan Anda saat ini.';
const route = apiResponse.route || 'knowledge';
const sources = apiResponse.sources || [];
const toolUsed = apiResponse.tool_used || null;
const toolResult = apiResponse.tool_result || null;

return [{
  json: {
    success: true,
    session_id: inputData.session_id,
    query: inputData.query,
    answer: answer,
    route: route,
    sources: sources,
    tool_used: toolUsed,
    tool_result: toolResult,
    metadata: {
      engine: 'agrisensa-rag-v2',
      timestamp: new Date().toISOString(),
      workflow: 'WF-01'
    }
  }
}];

// Build error response
const inputData = $('✅ Input Validator').item.json;
return [{
  json: {
    success: false,
    session_id: inputData.session_id,
    query: inputData.query,
    answer: 'Maaf, terjadi kesalahan pada sistem AI. Silakan coba kembali dalam beberapa saat.',
    error: 'API_ERROR',
    metadata: { engine: 'agrisensa-rag-v2', timestamp: new Date().toISOString(), workflow: 'WF-01' }
  }
}];
